/**
 * The "Fill with AI" card: shown wherever words without a meaning are, with
 * one button that fills every one of them (`fill.ts`). In the notebook it
 * covers the whole notebook; after an import, only the words that import
 * added.
 *
 * It names the learner's words and nothing else: how many have no meaning,
 * how many were filled, how many still wait. No allowance appears in any
 * line; when the day's AI runs out the words wait for tomorrow, and an
 * unconfirmed address is asked to confirm in the words the add-many screen
 * already uses.
 */
import { useEffect, useMemo, useRef, useState } from 'react';
import { auth as authApi } from '@/api/endpoints.js';
import { ApiError, isApiError } from '@/api/errors.js';
import { Button } from '@/components/ui/Button.js';
import { Icon } from '@/components/ui/Icon.js';
import { db } from '@/db/schema.js';
import { useAuth } from '@/features/auth/session.js';
import { ProOffer } from '@/features/billing/ProOffer.js';
import { offerable, useBilling } from '@/features/billing/state.js';
import { t } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { fillScope, useFill, wordsToFill, type FillResult } from './fill.js';
import { aiPausedUntil } from './quota.js';
import styles from './FillWithAi.module.css';

/**
 * From how many words an unconfirmed account is told before the run that it
 * may be cut short: the same rule as the add-many screen
 * (`UNCONFIRMED_NOTICE_MIN_WORDS` there), since the server fills only a few
 * cards before the address is confirmed and never says how many are left.
 */
const UNCONFIRMED_NOTICE_MIN_WORDS = 2;

interface FillWithAiProps {
  notebookId: string;
  /** Only these words (what an import added); every word of the notebook otherwise. */
  ids?: readonly string[];
  /** The title an import's result uses: "new words". */
  afterImport?: boolean;
  /** Brings the card into view and its button into focus as it appears (a link from Today). */
  focusOnArrival?: boolean;
}

export function FillWithAi({
  notebookId,
  ids,
  afterImport = false,
  focusOnArrival = false,
}: FillWithAiProps): React.JSX.Element | null {
  const idSet = useMemo(() => (ids === undefined ? undefined : new Set(ids)), [ids]);
  const scope = fillScope(idSet);
  const waiting = useLiveQuery<number | undefined>(
    async () => (await wordsToFill(notebookId, idSet)).length,
    undefined,
    [notebookId, scope],
  );
  const notebook = useLiveQuery(() => db.notebooks.get(notebookId), undefined, [notebookId]);
  const pausedUntil = useLiveQuery(() => aiPausedUntil(), undefined, []);
  const run = useFill((state) => (state.run?.notebookId === notebookId ? state.run : undefined));
  const start = useFill((state) => state.start);
  const clear = useFill((state) => state.clear);
  const unconfirmed = useAuth((state) => state.user?.emailVerified === false);
  // An Apple relay address is never shown (hiddenEmail.ts).
  const address = useAuth((state) => (state.user?.emailHidden === true ? undefined : state.user?.email));
  const refreshUser = useAuth((state) => state.refreshUser);
  const billing = useBilling((state) => state.state);
  const ensurePlan = useBilling((state) => state.ensure);
  const [noticeOpen, setNoticeOpen] = useState(false);
  const [resendNote, setResendNote] = useState<string | undefined>();
  const [resending, setResending] = useState(false);
  const card = useRef<HTMLElement>(null);

  useEffect(() => {
    ensurePlan();
  }, [ensurePlan]);

  const visible = waiting !== undefined && (waiting > 0 || run !== undefined);
  const arrived = useRef(false);
  useEffect(() => {
    if (!focusOnArrival || !visible || arrived.current) return;
    arrived.current = true;
    card.current?.scrollIntoView({ block: 'nearest' });
    card.current?.querySelector('button')?.focus({ preventScroll: true });
  }, [focusOnArrival, visible]);

  if (!visible) return null;

  const running = run?.running === true;
  // A finished run belongs to the place that started it: the import's
  // result does not report on the notebook's run, nor the other way round.
  const result = run !== undefined && !running && run.scope === scope ? run.result : undefined;
  const resting = pausedUntil !== undefined;
  const withPro = offerable(billing, notebook?.targetLang, notebook?.meaningLang);

  const go = (): void => {
    if (unconfirmed && waiting >= UNCONFIRMED_NOTICE_MIN_WORDS && !noticeOpen) {
      setNoticeOpen(true);
      setResendNote(undefined);
      return;
    }
    setNoticeOpen(false);
    void start(notebookId, { ...(idSet === undefined ? {} : { ids: idSet }), unconfirmed });
  };

  const resend = (): void => {
    setResending(true);
    authApi
      .resendVerification()
      .then(() => {
        setResendNote(t('auth.verifyResent'));
      })
      .catch((cause: unknown) => {
        if (isApiError(cause, 'offline')) setResendNote(t('error.offline'));
        else if (cause instanceof ApiError && cause.code === 'rate_limited')
          setResendNote(t('auth.verifyResendLater'));
        else if (cause instanceof ApiError && cause.code === 'mail_unavailable')
          setResendNote(t('auth.verifyMailUnavailable'));
        else if (cause instanceof ApiError && cause.code === 'already_verified') {
          void refreshUser();
          setNoticeOpen(false);
        } else setResendNote(t('error.generic'));
      })
      .finally(() => {
        setResending(false);
      });
  };

  const title = running
    ? t('fill.working')
    : result !== undefined && result.filled > 0
      ? t('fill.done', { count: result.filled })
      : t(afterImport ? 'fill.importTitle' : 'fill.title', { count: waiting });
  const askUnconfirmed =
    result?.outcome === 'unconfirmed' || result?.outcome === 'restUnconfirmed' || noticeOpen;
  const canRetry =
    result !== undefined &&
    waiting > 0 &&
    (result.outcome === 'offline' ||
      result.outcome === 'failed' ||
      result.outcome === 'declined' ||
      result.outcome === 'elsewhere');
  const offersStart = result === undefined && !running && !noticeOpen && !resting && waiting > 0;
  const progress = run?.progress;

  return (
    <section ref={card} className={styles.card} aria-labelledby={`fill-${scope}-title`}>
      <div className={styles.head}>
        <span className={styles.icon} aria-hidden="true">
          <Icon name="sparkles" size={18} weight={2} />
        </span>
        <div className={styles.text}>
          <h2 id={`fill-${scope}-title`} className={styles.title}>
            {title}
          </h2>
          <p className={styles.line} role={result === undefined ? undefined : 'status'}>
            {running
              ? t('fill.workingLine')
              : result !== undefined
                ? outcomeLine(result, waiting, withPro, address)
                : resting
                  ? t('ai.resting')
                  : t('fill.line')}
          </p>
        </div>
        {result !== undefined && (
          <button type="button" className={styles.close} aria-label={t('fill.hide')} onClick={clear}>
            <Icon name="close" size={16} weight={2} />
          </button>
        )}
      </div>

      {running && progress !== undefined && progress.total > 0 && (
        <div
          className={styles.track}
          role="progressbar"
          aria-label={t('fill.progressLabel')}
          aria-valuemin={0}
          aria-valuemax={progress.total}
          aria-valuenow={progress.settled}
        >
          <span
            className={styles.bar}
            style={{ width: `${String(Math.max(6, (progress.settled / progress.total) * 100))}%` }}
          />
        </div>
      )}

      {noticeOpen && (
        <div className={styles.notice}>
          <p className={styles.noticeTitle}>{t('ai.unconfirmedTitle')}</p>
          <p className={styles.noticeBody}>{t('ai.unconfirmedBody')}</p>
        </div>
      )}

      {resendNote !== undefined && (
        <p className={styles.note} role="status">
          {resendNote}
        </p>
      )}

      {(offersStart || canRetry || askUnconfirmed) && (
        <div className={styles.actions}>
          {askUnconfirmed && (
            <Button variant="secondary" busy={resending} onClick={resend}>
              {t('ai.unconfirmedResend')}
            </Button>
          )}
          {noticeOpen && <Button onClick={go}>{t('ai.unconfirmedSend')}</Button>}
          {offersStart && <Button onClick={go}>{t('fill.action', { count: waiting })}</Button>}
          {canRetry && <Button onClick={go}>{t('fill.retry')}</Button>}
        </div>
      )}

      {/* Stopped by the day's AI running out: the one moment Pro is worth
          naming, after the words are safe (they always are: they were
          saved before anything was asked of the AI). */}
      {!running && (resting || result?.outcome === 'rest' || result?.outcome === 'resting') && (
        <ProOffer occasion="resting" />
      )}
    </section>
  );
}

/** What became of the run, in the learner's words and with no allowance in it. */
function outcomeLine(
  result: FillResult,
  waiting: number,
  withPro: boolean,
  address: string | undefined,
): string {
  switch (result.outcome) {
    case 'done':
      return waiting > 0 ? t('fill.unfilled', { count: waiting }) : t('fill.allDone');
    case 'rest':
      return withPro ? t('fill.restPro', { count: waiting }) : t('fill.rest', { count: waiting });
    case 'restUnconfirmed':
      return t('ai.restSavedUnconfirmed', { count: waiting });
    case 'resting':
      return t('ai.resting');
    case 'unconfirmed':
      // The banner's own words, which name where the link went.
      return address === undefined ? t('fill.unconfirmed') : t('auth.verifyBanner', { email: address });
    case 'offline':
      return t('error.offline');
    case 'declined':
      return t('aiConsent.declined');
    case 'elsewhere':
      return t('fill.elsewhere');
    case 'failed':
      return t('ai.failed');
  }
}
